={{ JSON.stringify((() => {
  const history = $('Fetch Conversation History').all().map(i => i.json);
  const allText = history.map(h => (h.incoming_message || '') + ' ' + (h.ai_response || '')).join(' ') + ' ' + ($json.incomingMessage || '');

  const result = { phone_number: $json.phoneNumber };

  // Lead score is NOT written here. It is applied by the "Update Lead Score"
  // node via a conditional PATCH whose WHERE clause checks score_locked and
  // the rank policy atomically at write time — this eliminates the TOCTOU
  // window where a stale Fetch Lead result could overwrite a manual lock.

  if ($json.contactName) result.full_name = $json.contactName;

  const emailMatch = allText.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
  if (emailMatch) result.email = emailMatch[0];

  // Address — priority: AI-returned field > location-pin text > regex scan of
  // history + current message (full street words and common abbreviations).
  let address = $json.physicalAddress || null;
  const userMsgs = history.map(h => h.incoming_message || '');
  userMsgs.push($json.incomingMessage || '');
  if (!address) {
    const locRegex = /customer sent their location:\s*(.+?)(?:\s*\(coordinates?:[^)]*\)\s*)?$/i;
    userMsgs.forEach(m => {
      if (!address && m) {
        const lm = m.match(locRegex);
        if (lm && lm[1]) address = lm[1].replace(/[,\s]+$/, '').trim();
      }
    });
  }
  if (!address) {
    const addrRegex = /\d+\s+\w+(?:\s+\w+)*\s+(?:road|rd|street|st|avenue|ave|drive|dr|place|close|blvd|lane|ln|way|crescent|cres|boulevard|terrace|heights)(?:\s*,?\s*[\w-]+){0,4}/i;
    userMsgs.forEach(m => {
      if (!address && m) {
        const am = m.match(addrRegex);
        if (am) address = am[0].replace(/[,\s]+$/, '').trim();
      }
    });
  }
  // Normalize common street abbreviations to full words for consistent storage
  const STREET_ABBREVIATIONS = {
    'ave': 'Avenue', 'rd': 'Road', 'st': 'Street', 'dr': 'Drive',
    'pl': 'Place', 'cres': 'Crescent', 'ln': 'Lane', 'blvd': 'Boulevard',
    'terr': 'Terrace', 'hts': 'Heights', 'cl': 'Close'
  };
  if (address) {
    result.physical_address = address.replace(
      /\b(ave|rd|st|dr|pl|cres|ln|blvd|terr|hts|cl)\.?\b/gi,
      (m, k) => STREET_ABBREVIATIONS[k.toLowerCase()] || m
    );
  }

  // Garment interest is captured via product_interest below (no package scan).
  if ($json.orderTrack) result.order_track = $json.orderTrack;

  // Sticky escalation — set when true, never overwrite back to false
  if ($json.needsEscalation === true) result.needs_escalation = true;

  // Alternative contact number (normalized in Process Response)
  if ($json.preferredContactNumber) result.preferred_contact_number = $json.preferredContactNumber;

  // Qualification answers captured by the AI (structured JSON output)
  if ($json.productInterest) result.product_interest = $json.productInterest;
  if ($json.householdSize) result.household_size = $json.householdSize;
  if ($json.internetUsage) result.internet_usage = $json.internetUsage;

  // Status is advanced (new -> contacted) by the "Advance Lead Status" node
  // after this upsert, via a conditional PATCH — an atomic guard that cannot
  // downgrade statuses set by campaign classification (lost/qualified).

  // Follow-up — only write when (re)requested so pending follow-ups are preserved
  if ($json.followUpRequested) {
    result.follow_up_requested = true;
    result.follow_up_date = $json.followUpDate;
    result.follow_up_sent = false;
    result.follow_up_sent_at = null;
  }

  return result;
})()) }}

