    const emailMatch = text.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
    if (emailMatch) email = emailMatch[0];
  }

  // Extract address (look for road/street/avenue patterns in user messages)
  if (!address && h.incoming_message) {
    const addrMatch = h.incoming_message.match(/\d+\s+\w+\s+(?:road|street|avenue|drive|place|close|blvd)\s*,?\s*\w+/i);
    if (addrMatch) address = addrMatch[0];
  }

});

