const items = $input.all();
// If conversation history is empty, pass through a placeholder so downstream nodes still execute
if (items.length === 0) {
  return [{ json: { phone_number: $('Extract Message').first().json.phoneNumber, incoming_message: null, ai_response: null, lead_score: null, timestamp: null, no_history: true } }];
}
// Only pass through the first item to prevent downstream HTTP nodes (Fetch Products, Fetch Lead)
// from running once per history item, which would duplicate the product catalog.
// Full history is accessed directly via $('Fetch Conversation History').all() in Build OpenRouter Request.
return [items[0]];

const handover = $('Prepare Chatwoot Handover').first().json;
const phoneNumber = handover.phoneNumber;
const contactName = handover.contactName;
const email = handover.email;

const baseUrl = 'http://chatwoot-rails:3000/api/v1/accounts/1';
const headers = {
  'api_access_token': '<REDACTED>',
  'Content-Type': 'application/json'
};

// Search for existing contact by phone number - paginate through all results
let contactId = null;
const searchPhone = `+${phoneNumber}`;
let page = 1;

while (!contactId && page <= 10) {
  let searchResp;
  try {
    searchResp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${baseUrl}/contacts?search=${encodeURIComponent(phoneNumber)}&page=${page}`,
      headers,
      json: true,
      timeout: 10000
    });
  } catch (e) {
    break;
  }

  const contacts = searchResp.payload || [];
  if (contacts.length === 0) break;

  for (const c of contacts) {
    if (c.phone_number === searchPhone || c.phone_number === phoneNumber ||
        c.identifier === searchPhone || c.identifier === phoneNumber) {
      contactId = c.id;
      break;
    }
  }
  page++;
}

// If not found, create new contact
if (!contactId) {
  try {
    const createResp = await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/contacts`,
      headers,
      body: {
        name: contactName,
        phone_number: searchPhone,
        email: email || null,
        identifier: searchPhone
      },
      json: true,
      timeout: 10000
    });
    // Chatwoot create response: { payload: { contact: { id: ... } } }
    contactId = createResp.payload?.contact?.id || createResp.id || createResp.payload?.id;
    if (!contactId) {
      throw new Error('Contact created but no ID found in response: ' + JSON.stringify(createResp).substring(0, 500));
    }
  } catch (e) {
    // Create failed - try searching again with broader terms
    page = 1;
    while (!contactId && page <= 10) {
      let searchResp;
      try {
        searchResp = await this.helpers.httpRequest({
          method: 'GET',
          url: `${baseUrl}/contacts?search=${encodeURIComponent(searchPhone)}&page=${page}`,
          headers,
          json: true,
          timeout: 10000
        });
      } catch (e2) {
        break;
      }
      const contacts = searchResp.payload || [];
      if (contacts.length === 0) break;
      for (const c of contacts) {
        if (c.phone_number === searchPhone || c.identifier === searchPhone) {
          contactId = c.id;
          break;
        }
      }
      page++;
    }
    if (!contactId) {
      throw new Error(`Failed to find or create contact: ${e.message}`);
    }
  }
}

return { json: { id: contactId, phoneNumber, contactName, email, inboxId: handover.inboxId } };

// The n8n Error Trigger outputs: { execution: { id, mode }, workflow: { id, name }, nodes: [{ name, error: { message, stack } }] }
const trigger = $json;

// Extract error details from the nodes array (first failed node)
const failedNode = (trigger.nodes && trigger.nodes[0]) || {};
const nodeError = failedNode.error || {};
const errorMsg = nodeError.message || trigger.message || 'Unknown error';
const nodeName = failedNode.name || (trigger.node && trigger.node.name) || 'Unknown node';
const stack = nodeError.stack || trigger.stack || trigger.stacktrace || '';

const workflowName = (trigger.workflow && trigger.workflow.name) || 'Eastern Wear - Layla Inbound AI';
const workflowId = (trigger.workflow && trigger.workflow.id) || 'kW4ELXolGnYx2AvB';
const workflowUrl = 'https://n8n.horizonafrica.co.za/workflow/' + workflowId;
const timestamp = new Date().toISOString();
const executionId = (trigger.execution && trigger.execution.id) || 'Unknown';
const executionMode = (trigger.execution && trigger.execution.mode) || 'unknown';

const htmlContent = `<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #dc3545; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;">
    <h1 style="color: white; margin: 0;">⚠️ Layla WhatsApp Bot Error</h1>
    <p style="color: white; margin: 5px 0 0 0;">The Inbound AI Lead Qualification workflow failed</p>
  </div>
  <div style="padding: 20px; border: 1px solid #ddd; border-top: none; border-radius: 0 0 10px 10px;">
    <h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px;">Error Details</h2>
    <table style="width: 100%; border-collapse: collapse;">
      <tr><td style="padding: 8px; font-weight: bold; width: 180px;">Workflow:</td><td style="padding: 8px;">${workflowName}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Failed Node:</td><td style="padding: 8px; color: #dc3545;">${nodeName}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Error:</td><td style="padding: 8px; color: #dc3545;">${errorMsg}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Execution ID:</td><td style="padding: 8px;">${executionId} (mode: ${executionMode})</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Time:</td><td style="padding: 8px;">${timestamp}</td></tr>
    </table>
    ${stack ? `<h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px; margin-top: 20px;">Stack Trace</h2>
    <pre style="background: #f8f8f8; padding: 10px; border-radius: 5px; overflow-x: auto; font-size: 12px;">${String(stack).substring(0, 2000)}</pre>` : ''}
    <h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px; margin-top: 20px;">Action Required</h2>
    <ul style="padding-left: 20px;">
      <li style="padding: 5px 0;">Check the workflow execution: <a href="${workflowUrl}">Open n8n Workflow</a></li>
      <li style="padding: 5px 0;">Layla is NOT responding to WhatsApp messages while this error persists</li>
      <li style="padding: 5px 0;">Review the failed node and fix the issue</li>
      <li style="padding: 5px 0;">Re-publish the workflow after fixing</li>
    </ul>
    <hr style="margin-top: 20px; border: none; border-top: 1px solid #ddd;">
    <p style="color: #999; font-size: 12px; text-align: center;">This alert was sent by the n8n Error Trigger on the Inbound AI workflow</p>
  </div>
</div>`;

return { json: {
  sender: { name: 'Eastern Wear Layla Alerts', email: 'keshlan@horizonafrica.co.za' },
  to: [{ email: 'sifosman@gmail.com', name: 'Sif' }],
  subject: '⚠️ Layla WhatsApp Bot Error - ' + String(errorMsg).substring(0, 60),
  htmlContent: htmlContent
} };

// Verify AI Response (Eastern Wear) — fact-checks the AI reply against the
// live Shopify catalogue BEFORE anything reaches the customer. Wrong prices,
// discounts or telecoms content are flagged so the reply can be regenerated;
// once the retry budget is spent a safe fallback is sent instead.
const openrouterResult = $input.first().json;
const req = $('Build OpenRouter Request').first().json;

// How many correction attempts have already run in this execution?
let retryCount = 0;
try {
  const prev = $('Build Correction Request').first().json;
  retryCount = (prev && prev.retryCount) || 0;
} catch (e) { /* first pass — correction node has not run yet */ }

// If the AI call itself failed there is nothing to verify — route past the
// Jev verifier (safeToSend 'no' -> Check Accuracy false) and skip correction
// retries (retryAllowed 'no'), so the customer gets the safe fallback and a
// consultant follow-up instead of a crashed Jev call on an undefined request.
const aiCallFailed = !!openrouterResult?.error || !openrouterResult?.choices?.length;
if (aiCallFailed) {
  return { json: Object.assign({}, openrouterResult, { _verify: { safeToSend: 'no', skipped: 'ai_call_failed', issues: ['AI call failed — technical error'], retryCount: retryCount, retryAllowed: 'no' } }) };
}

// Extract the customer-facing reply text from the JSON envelope
const rawContent = openrouterResult.choices[0].message && openrouterResult.choices[0].message.content || '';
let replyText = rawContent;
try {
  const parsed = JSON.parse(rawContent);
  replyText = parsed.reply || parsed.response || parsed.message || rawContent;
} catch (e) {
  const fenced = rawContent.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fenced) {
    try { const p2 = JSON.parse(fenced[1].trim()); replyText = p2.reply || rawContent; } catch (e2) {}
  }
}

// Authoritative catalog facts (live Shopify in-stock catalogue)
const rands = c => { const r = c / 100; return 'R' + (r % 1 === 0 ? r : r.toFixed(2)); };
let products = [];
try { products = $('Fetch Products').all().map(i => i.json).filter(p => p && p.title); } catch (e) {}
const SHIPPING = [120, 150];
const validPrices = new Set(SHIPPING);
const addPrice = cents => {
  if (cents == null || cents <= 0) return;
  const r = cents / 100;
  validPrices.add(r);
  validPrices.add(Math.round(r / 2 * 100) / 100); // 50% imported-order deposit
  SHIPPING.forEach(s => validPrices.add(r + s));   // item + delivery total
};
for (const p of products) for (const v of (p.shopify_variants || [])) addPrice(v.price_cents);

// M5: website-button referral — the product the customer was viewing is
// resolved by 'Lookup Product Context'; its variants are catalog facts too.
let refProduct = null;
try {
  refProduct = (($('Lookup Product Context').all() || [])
    .map(i => i.json)
    .find(p => p && p.handle)) || null;
  if (refProduct) for (const v of (refProduct.shopify_variants || [])) addPrice(v.price_cents);
} catch (e) {}

const issues = [];
let m;

// 1) Prices — every "R<amount>"/"ZAR <amount>" quoted must be a catalog price,
// a shipping fee, a 50% deposit or an item+shipping total.
const priceRe = /\b(?:ZAR|R)\s*(\d[\d\s,]*(?:\.\d{1,2})?)/gi;
const quotedPrices = [];
while ((m = priceRe.exec(replyText)) !== null) {
  const val = parseFloat(m[1].replace(/[\s,]/g, ''));
  if (!isNaN(val)) quotedPrices.push(val);
}
const badPrices = [...new Set(quotedPrices.filter(v => !validPrices.has(v)))];
if (badPrices.length) issues.push('quoted prices not in catalog/shipping/deposit: ' + badPrices.map(v => 'R' + v).join(', '));

// 2) Scope — Layla must never talk about the previous telecoms business
if (/\b(telkom|fibre|fiber|mbps|gbps|lte|uncapped|horizon africa|internet package|router)\b/i.test(replyText)) {
  issues.push('reply mentions telecoms/Horizon Africa content — out of scope for Eastern Wear');
}

// 2b) Never redirect customers to another phone/WhatsApp number — handovers
// happen inside this chat. (The customer's own number being confirmed back is fine.)
{
  let ownDigits = '';
  try { ownDigits = String($('Extract Message').first().json.phoneNumber || ''); } catch (e) {}
  const nums = (replyText.match(/(?:\+?27|0)[\s-]?\d{2}[\s-]?\d{3}[\s-]?\d{4}/g) || []).map(n => n.replace(/\D/g, '').replace(/^0/, '27'));
  let knownNums = [ownDigits];
  try { const l = $('Fetch Lead').first().json || {}; knownNums.push(String(l.preferred_contact_number || ''), String(l.phone_number || '')); } catch (e) {}
  if (nums.some(n => !knownNums.includes(n))) issues.push('reply gives out a phone number — handovers must stay in this chat');
}

// 3) Discounts — never offered (a refusal like "we don't offer discounts" is fine)
const discountClaim = /\b\d{1,2}\s*%\s*off\b|\bpromo code\b|\bdiscount code\b|\bspecial price\b|\bi can (?:give|offer) you (?:a )?(?:discount|better price)/i.test(replyText);
if (discountClaim) issues.push('reply offers a discount/special price');

// 4) Catalog outage — prices quoted but nothing to verify against
if (!products.length && !refProduct && quotedPrices.some(v => !SHIPPING.includes(v))) {
  issues.push('product catalog unavailable — prices could not be verified');
}

// Build the Jev (System One decision model) verification request. The
// deterministic checks above already ran; Jev performs the deeper semantic
// check — invented facts, overpromises, misleading claims — that regex can't.
// Include each product's description so attributes stated there (fabric,
// India/SA size) are recognised as catalog facts rather than invented claims.
const catalogLinesJev = products.map(p => {
  const vs = (p.shopify_variants || []);
  let line = '- ' + p.title + (p.category ? ' [' + p.category + ']' : '');
  line += ' — ' + (vs.length ? vs.map(v => (v.title && v.title !== 'Default Title' ? v.title + ' ' : '') + (v.price_cents ? rands(v.price_cents) : 'price on request')).join('; ') : 'price on request');
  if (p.description) line += ' | ' + String(p.description).replace(/\s+/g, ' ').slice(0, 200);
  return line;
});

if (refProduct) {
  let line = '- ' + refProduct.title + ' (website referral product, handle /products/' + refProduct.handle + ')';
  const variants = (refProduct.shopify_variants || []);
  if (variants.length) {
    line += ' | variants: ' + variants.map(v => {
      const price = v.price_cents != null ? 'R' + (v.price_cents / 100).toFixed(v.price_cents % 100 === 0 ? 0 : 2) : 'price on request';
      const qty = v.inventory_qty != null ? v.inventory_qty : 0;
      return (v.title || 'Standard') + ' ' + price + ' (' + ((v.available && qty > 0) ? qty + ' in stock' : 'out of stock') + ')';
    }).join('; ');
  }
  if (refProduct.description) line += ' | ' + refProduct.description;
  catalogLinesJev.push(line);
}

// Give Jev the recent conversation so references like "previously
// recommended" or "the saree we discussed" are verifiable rather than
// being flagged as unverifiable/invented.
let historyLines = [];
try {
  historyLines = $('Fetch Conversation History').all()
    .map(i => i.json)
    .filter(h => h && (h.incoming_message || h.ai_response))
    .slice(0, 8)
    .reverse()
    .map(h => {
      let s = '';
      if (h.incoming_message) s += 'Customer: ' + String(h.incoming_message).slice(0, 300);
      if (h.ai_response) s += (s ? ' | ' : '') + 'Agent: ' + String(h.ai_response).slice(0, 300);
      return s;
    });
} catch (e) {}

// Known customer facts — the stored lead record is authoritative context for
// Jev. Without it, correct references like "your address in Mayfair" or "the
// number ending 5575" look like invented details and get falsely rejected.
let lead = {};
try { lead = $('Fetch Lead').first().json || {}; } catch (e) {}
const knownLines = [];
if (lead && !lead.error) {
  if (lead.full_name) knownLines.push('name: ' + lead.full_name);
  if (lead.email) knownLines.push('email: ' + lead.email);
  if (lead.physical_address) knownLines.push('address on file: ' + lead.physical_address);
  if (lead.preferred_contact_number) knownLines.push('preferred contact number: ' + lead.preferred_contact_number);
  const TELECOM_RE = /telkom|fibre|fiber|mbps|\blte\b|uncapped|internet|router|people|person|streaming|gaming/i;
  const clean = v => (v != null && v !== '' && !TELECOM_RE.test(String(v))) ? String(v) : null;
  if (clean(lead.product_interest)) knownLines.push('interested in: ' + clean(lead.product_interest));
  if (clean(lead.household_size)) knownLines.push('size: ' + clean(lead.household_size));
  if (clean(lead.internet_usage)) knownLines.push('occasion / style: ' + clean(lead.internet_usage));
}

const jevRequest = {
  model: 'typesafe/jev-1.13',
  state: {
    context: 'Eastern Wear by Kersh is a South African boutique (the Bluff, Durban) selling traditional Indian / Eastern wear (sarees, anarkalis, lehengas, dhotis, co-ords, jewellery, kiddies wear). product_catalog lists live in-stock items; their titles, prices, sizes and descriptions (e.g. India size XL = SA size 36) are facts. Stock is usually one of each item. Authoritative business terms: free collection on the Bluff Mon-Fri 09:00-17:00 by appointment; standard delivery R120 (3-5 working days, estimate); express delivery R150 (1-3 working days, estimate); dispatch within 24-48h after payment; full payment confirms stock-on-hand orders and stock cannot be reserved before payment; imported orders are placed every Friday from India, take about six weeks, need a minimum 50% deposit with the balance on arrival (so a deposit of half a catalog price, or a catalog price plus R120/R150 delivery, are correct figures); 24-hour voluntary exchange; 7-day ECTA cancellation where applicable; payment links open the website checkout (Payflex available); never offer discounts or negotiate; contact is this WhatsApp chat or orders@easternwearbykersh.com — the agent must never give out any other phone number. The agent must never discuss telecoms, internet or Horizon Africa. known_customer lists details already on file — they count as verified facts. Use conversation_history to verify references to earlier turns. Confirming a callback time or contact detail the customer asked for is acknowledgement, not a promise. Honest deferral to the team for anything not covered is correct and safe. Lines marked as a website referral product are catalog facts.',
    customer_message: req.messageText,
    conversation_history: historyLines.length ? historyLines.join('\n') : '(no prior conversation)',
    known_customer: knownLines.length ? knownLines.join('\n') : '(no customer details on file)',
    ai_reply: replyText,
    product_catalog: catalogLinesJev.join('\n')
  },
  questions: {
    facts_correct: {
      type: 'noul',
      instructions: 'Are the item names, prices, sizes, delivery fees/times and business terms stated in ai_reply correct per product_catalog and the context? Conversational phrasing is fine — only factual accuracy matters. Attributes in product descriptions (fabric, pieces, India/SA size) count as catalog facts. Statements matching known_customer (name, address, contact details) are verified facts, not invented. References to earlier conversation are fine if supported by conversation_history. If the customer asked about something outside the catalog and the reply defers to a consultant without stating invented specifics, that counts as correct.',
      criteria: { 'true': 'Every item, price, size, fee and business term stated is correct per the catalog/context; wording may be conversational; honest deferral to the team for out-of-catalog topics is acceptable', 'false': 'At least one stated item, price, size, fee or term is wrong or invented' }
    },
    no_overpromises: {
      type: 'noul',
      instructions: 'Is ai_reply free of unsupported promises — e.g. guaranteed or reserved stock before payment, guaranteed delivery dates, invented discounts or promotions, invented return terms? Acknowledging or repeating a callback time or contact detail the customer themselves requested is confirmation of their request, not an unsupported promise.',
      criteria: { 'true': 'No unsupported promises or guarantees are made', 'false': 'The reply promises something the business has not committed to' }
    },
    appropriate_response: {
      type: 'noul',
      instructions: 'Is ai_reply an accurate, honest response in the context of customer_message and conversation_history, staying within Eastern Wear by Kersh\'s clothing business — it does not discuss telecoms/internet, invent policies, or fabricate information? Confirming details the customer just provided (a requested callback time, an address, a contact number) is appropriate. A reply that honestly says the team will confirm out-of-catalog details (measurements, imported items, returns approvals) is appropriate.',
      criteria: { 'true': 'The reply is accurate, honest, contextually appropriate and stays on Eastern Wear by Kersh business; deferring out-of-catalog questions to the team is appropriate', 'false': 'The reply misleads the customer, invents policy, fabricates information, or talks about telecoms/internet' }
    }
  }
};

return { json: Object.assign({}, openrouterResult, { _verify: {
  safeToSend: issues.length === 0 ? 'yes' : 'no',
  issues: issues,
  retryCount: retryCount,
  retryAllowed: retryCount < 2 ? 'yes' : 'no',
  replyChecked: replyText.slice(0, 500)
}, jevRequest: jevRequest }) };

// Build Correction Request — sends the flagged reply back to the model with
// the authoritative catalog so it can fix incorrect prices/speeds/claims.
const req = $('Build OpenRouter Request').first().json;
const verify = ($input.first().json._verify) || {};

const rands = x => { const r = x / 100; return 'R' + (r % 1 === 0 ? r : r.toFixed(2)); };
let products = [];
try { products = $('Fetch Products').all().map(i => i.json).filter(p => p && p.title); } catch (e) {}
const catalogLines = products.map(p => {
  const vs = (p.shopify_variants || []);
  return '- ' + p.title + ' — ' + (vs.length ? vs.map(v => (v.title && v.title !== 'Default Title' ? v.title + ' ' : '') + (v.price_cents ? rands(v.price_cents) : 'price on request')).join('; ') : 'price on request');
});
catalogLines.push('- Delivery: standard R120 (3-5 working days), express R150 (1-3 working days), collection on the Bluff free. Imported orders: ~6 weeks, minimum 50% deposit. No discounts ever.');

const badReply = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '';

const messages = (req.openrouterRequest.messages || []).slice();
if (badReply) messages.push({ role: 'assistant', content: badReply });
messages.push({ role: 'user', content:
  'CORRECTION REQUIRED — your previous reply contained information that does not match our records: ' +
  (verify.issues || []).join('; ') + '.\n' +
  'Authoritative product catalog (only these facts may be quoted):\n' + catalogLines.join('\n') +
  '\nRewrite the reply. Fix or remove ONLY the incorrect details — never mention telecoms, internet or Horizon Africa; keep answering the customer\'s question directly when the catalog covers it. Do not defer to the team for questions the catalog can answer. Only if the customer asked something genuinely not covered by the catalog (e.g. exact measurements, items not in stock, return approvals) should you say the team will confirm and set needsEscalation to true. Respond with the same JSON object format.'
});

return { json: {
  openrouterRequest: {
    model: req.openrouterRequest.model,
    messages: messages,
    temperature: 0.2,
    max_tokens: 1000,
    response_format: { type: 'json_object' }
  },
  retryCount: (verify.retryCount || 0) + 1,
  correctionIssues: verify.issues || []
} };

// Build Safe Fallback — retry budget exhausted and the reply still failed
// verification. Never send the incorrect info: send a safe holding message
// and flag escalation so a consultant follows up with correct details.
const verify = ($input.first().json._verify) || {};
const fallback = {
  reply: "Thanks for your patience! I want to make sure you get the correct details — one of our consultants will confirm and get back to you shortly.",
  needsEscalation: true
};
return { json: {
  choices: [{ message: { content: JSON.stringify(fallback) } }],
  _fallback: { reason: 'verification_failed', issues: verify.issues || [], retryCount: verify.retryCount || 0 }
} };

// Evaluate Jev Verdict — reads Jev's typed decisions and decides whether the
// reply is semantically safe to send. The deterministic price/speed checks in
// Verify AI Response already passed; Jev is the second-line judge for
// hallucinations, invented facts and overpromises that regex can't catch.
const jevResult = $input.first().json;
const upstream = $('Verify AI Response').first().json;
const verify = upstream._verify || {};
const retriesUsed = verify.retryCount || 0;

// Jev call failed/unreachable (error object or missing answers). Deterministic
// checks already passed, so let the reply through rather than blocking every
// customer conversation during a Jev/OpenRouter outage.
const answers = jevResult && jevResult.answers;
if (!answers) {
  return { json: Object.assign({}, upstream, { _verify: Object.assign({}, verify, {
    safeToSend: 'yes',
    jevSkipped: true,
    retryAllowed: 'no',
    jevError: (jevResult && jevResult.error && jevResult.error.message) || 'no answers in Jev response'
  }) }) };
}

// Facts and overpromises stay strict; appropriateness is subjective and Jev
// scores it inconsistently on short/qualified replies, so a lower bar avoids
// false rejections of correct catalog answers.
const THRESHOLDS = {
  facts_correct: 0.6,
  no_overpromises: 0.6,
  appropriate_response: 0.45
};
const labels = {
  facts_correct: 'Jev: prices/speeds/product facts do not all match the catalog',
  no_overpromises: 'Jev: reply may contain unsupported promises or guarantees',
  appropriate_response: 'Jev: reply may mislead the customer or misattribute the service'
};
const issues = [];
for (const key of Object.keys(labels)) {
  const a = answers[key];
  if (a && a.type === 'noul' && typeof a.noul === 'number' && a.noul < THRESHOLDS[key]) {
    issues.push(labels[key] + ' (p=' + a.noul.toFixed(2) + ')');
  }
}

return { json: Object.assign({}, upstream, { _verify: Object.assign({}, verify, {
  safeToSend: issues.length === 0 ? 'yes' : 'no',
  issues: issues,
  retryAllowed: retriesUsed < 2 ? 'yes' : 'no',
  jev: { answers: answers, cost: (jevResult.usage && jevResult.usage.cost) || null }
}) }) };
